    claim(chanceValues[0],'forgeSuccessRate');claim(chanceValues[1],'forgeStayRate');claim(chanceValues[3],'forgeDestroyRate');
    const chanceCols=[...forgePage.querySelectorAll('#forgeCard .grid-cols-4 > div')];if(chanceCols[2])chanceCols[2].classList.add('hidden');
    const slots=[...forgePage.querySelectorAll('#forgeCard .grid-cols-3 > button')];
    claim(slots[0],'forgeUseShield');claim(slots[1],'forgeUseWhetstone');claim(slots[2],'forgeSkipBellows');if(slots[2]){slots[2].checked=false;slots[2].addEventListener('click',()=>{slots[2].checked=!slots[2].checked;slots[2].classList.toggle('equipped',slots[2].checked);slots[2].setAttribute('aria-pressed',String(slots[2].checked))})}
    const shieldCopy=slots[0]?.querySelector('span:last-child');const whetstoneCopy=slots[1]?.querySelector('span:last-child');claim(shieldCopy,'forgeShieldCopy');claim(whetstoneCopy,'forgeWhetstoneCopy');
